const video = document.createElement("video");
video.muted = true;
video.defaultMuted = true;
video.autoplay = false;
video.playsInline = true;
video.controls = false;
video.playbackRate = 1;
video.defaultPlaybackRate = 1;
video.preload = "none";
container.append(video);

// Copy the public imports and createPlayer factory from Applied configuration.
const player = await createPlayer({
  key: playerKey,
  defaultContainer: container,
  defaultVideoElement: video,
  playback: { muted: true, autoplay: true, preventSeeking: false },
  defaultLogLevel: 0,
});
const source = player.sources.add({
  resources: [{ url: mediaUrl, type: "hls" }],
  contentType: "content",
}, { attach: false, loadControl: 0 });
source.logLevel = 0;
source.currentTime = 0;
source.playbackRate = 1;
// Register source observers before starting data loading.
player.sources.attachVideo(source, { video, container });
video.controls = false;
source.loadControl = 2;
await source.play();

import { Player, LogLevel } from "bitmovin-player/modules/bitmovinplayer-core";
// Register EngineBitmovin, RendererMSE, HLS, ABR, MP4 and TS modules first.
const player = new Player(container, {
  key: playerKey,
  playback: {
    muted: true, autoplay: false, audioLanguage: "en",
    preferredTech: [{ player: "html5", streaming: "hls" }],
  },
  ui: false, analytics: false,
  storage: { disableStorageApi: true },
  buffer: {
    audio: { forwardduration: 12, backwardduration: 6 },
    video: { forwardduration: 12, backwardduration: 6 },
  },
  logs: { level: LogLevel.OFF, bitmovin: false },
});
player.setVideoElement(video);
await player.load({ hls: mediaUrl, options: { startOffset: 0 } }, "html5.hls");
await player.play();

import Hls from "hls.js";
import workerURL from "hls.js/dist/hls.worker.js?url";

const hls = new Hls({
  debug: false, autoStartLoad: true, startPosition: 0,
  audioPreference: { lang: "en" }, preferManagedMediaSource: false,
  enableWorker: false, workerPath: workerURL,
  lowLatencyMode: false, enableInterstitialPlayback: false,
  maxBufferLength: 12, maxMaxBufferLength: 12,
  backBufferLength: 6, frontBufferFlushThreshold: 12,
});
hls.attachMedia(video);
hls.loadSource(mediaUrl);
await video.play();

import shaka from "shaka-player/dist/shaka-player.hls-es2021.js";

shaka.polyfill.installAll();
const player = new shaka.Player();
if (!player.configure({
  preferredAudio: [{ language: "en", role: "", label: "", channelCount: 2,
    codec: "", spatialAudio: false }],
  streaming: {
    preferNativeHls: false, fallbackToNativeHlsOnMseError: false,
    useNativeHlsForFairPlay: false, lowLatencyMode: false,
    bufferingGoal: 12, bufferBehind: 6, rebufferingGoal: 0,
  },
  cmcd: { enabled: false }, cmsd: { enabled: false },
  ads: { disableHLSInterstitial: true, disableDASHInterstitial: true, disableSVTA: true },
})) throw new Error("Configuration rejected");
await player.attach(video);
const loading = player.load(mediaUrl, 0, "application/x-mpegurl");
await Promise.all([loading, video.play()]);
